"""Cross-language contract tests verifying manifest compatibility between Android and Python."""

import json
import unittest

from workers.processor.src.models import (
    GeminiAnalysisResult,
    JobManifest,
    JobResults,
    JobStatus,
    MediaInfo,
    StageStates,
    StageStatus,
)


class TestManifestContract(unittest.TestCase):
    """Verifies that manifests generated by Android (CloudJobManifest.toJson())

    are 100% compatible with Python JobManifest.from_json() and vice versa.
    """

    def setUp(self):
        # Sample JSON produced by Android CloudJobManifest.toJson()
        self.android_json = json.dumps({
            "schema_version": 1,
            "record_revision": 2,
            "version": 1,
            "job_id": "test-item-uuid-1234",
            "item_id": "test-item-uuid-1234",
            "source": "MEDIA_SHARE",
            "original_url": "https://www.instagram.com/reel/C7xyz123/",
            "caption": "A quick tip for productivity",
            "user_notes": "Remember step 2",
            "category": "Technology",
            "user_tags": ["productivity", "tips"],
            "status": "QUEUED",
            "claimed_by": "gha-worker-run-99",
            "claimed_at": 1730000000000,
            "lease_timeout_ms": 900000,
            "etag": "rev_2_etag",
            "created_at": 1729999000000,
            "updated_at": 1730000000000,
            "retry_count": 1,
            "max_retries": 3,
            "next_retry_at": 1730000060000,
            "error_message": "Transient network timeout",
            "media": {
                "file_name": "video_1234.mp4",
                "mime_type": "video/mp4",
                "drive_file_id": "drive_media_file_id_5678",
                "size_bytes": 1048576,
                "duration_ms": 30000
            },
            "stages": {
                "acquisition": "SKIPPED",
                "audio_extraction": "SUCCEEDED",
                "transcription": "SUCCEEDED",
                "ocr": "PENDING",
                "gemini_analysis": "PENDING"
            },
            "results": {
                "audio_drive_file_id": "drive_audio_file_id_9999",
                "audio_size_bytes": 524288,
                "transcript": "Hello and welcome to this reel.",
                "transcript_model": "whisper-base",
                "ocr_text": "Tip 1: Focus",
                "analysis": {
                    "summary": "Short productivity reel",
                    "detailed_summary": "Explains how to focus and achieve goals.",
                    "main_topic": "Focus",
                    "category": "Technology",
                    "keywords": ["focus", "goals"],
                    "tags": ["productivity", "habits"],
                    "key_takeaways": ["Start early"],
                    "important_concepts": ["Deep work"],
                    "actionable_steps": ["Turn off phone"],
                    "model_name": "gemini-3.6-flash",
                    "generated_at": 1730000100000
                }
            }
        }, indent=2)

    def test_python_parses_android_manifest(self):
        manifest = JobManifest.from_json(self.android_json)

        self.assertEqual("test-item-uuid-1234", manifest.item_id)
        self.assertEqual("test-item-uuid-1234", manifest.job_id)
        self.assertEqual(1, manifest.schema_version)
        self.assertEqual(2, manifest.record_revision)
        self.assertEqual(1, manifest.version)
        self.assertEqual("MEDIA_SHARE", manifest.source)
        self.assertEqual("https://www.instagram.com/reel/C7xyz123/", manifest.original_url)
        self.assertEqual("A quick tip for productivity", manifest.caption)
        self.assertEqual("Remember step 2", manifest.user_notes)
        self.assertEqual("Technology", manifest.category)
        self.assertEqual(["productivity", "tips"], manifest.user_tags)
        self.assertEqual(JobStatus.QUEUED, manifest.status)
        self.assertEqual("gha-worker-run-99", manifest.claimed_by)
        self.assertEqual(1730000000000, manifest.claimed_at)
        self.assertEqual(900000, manifest.lease_timeout_ms)
        self.assertEqual("rev_2_etag", manifest.etag)
        self.assertEqual(1729999000000, manifest.created_at)
        self.assertEqual(1730000000000, manifest.updated_at)
        self.assertEqual(1, manifest.retry_count)
        self.assertEqual(3, manifest.max_retries)
        self.assertEqual(1730000060000, manifest.next_retry_at)
        self.assertEqual("Transient network timeout", manifest.error_message)

        # Media
        self.assertIsNotNone(manifest.media)
        self.assertEqual("video_1234.mp4", manifest.media.file_name)
        self.assertEqual("video/mp4", manifest.media.mime_type)
        self.assertEqual("drive_media_file_id_5678", manifest.media.drive_file_id)
        self.assertEqual(1048576, manifest.media.size_bytes)
        self.assertEqual(30000, manifest.media.duration_ms)

        # Stages
        self.assertEqual(StageStatus.SKIPPED, manifest.stages.acquisition)
        self.assertEqual(StageStatus.SUCCEEDED, manifest.stages.audio_extraction)
        self.assertEqual(StageStatus.SUCCEEDED, manifest.stages.transcription)
        self.assertEqual(StageStatus.PENDING, manifest.stages.ocr)
        self.assertEqual(StageStatus.PENDING, manifest.stages.gemini_analysis)

        # Results
        self.assertEqual("drive_audio_file_id_9999", manifest.results.audio_drive_file_id)
        self.assertEqual(524288, manifest.results.audio_size_bytes)
        self.assertEqual("Hello and welcome to this reel.", manifest.results.transcript)
        self.assertEqual("whisper-base", manifest.results.transcript_model)
        self.assertEqual("Tip 1: Focus", manifest.results.ocr_text)

        # Analysis
        self.assertIsNotNone(manifest.results.analysis)
        self.assertEqual("Short productivity reel", manifest.results.analysis.summary)
        self.assertEqual("Explains how to focus and achieve goals.", manifest.results.analysis.detailed_summary)
        self.assertEqual("Focus", manifest.results.analysis.main_topic)
        self.assertEqual("Technology", manifest.results.analysis.category)
        self.assertEqual(["focus", "goals"], manifest.results.analysis.keywords)
        self.assertEqual(["productivity", "habits"], manifest.results.analysis.tags)
        self.assertEqual(["Start early"], manifest.results.analysis.keyTakeaways if hasattr(manifest.results.analysis, 'keyTakeaways') else manifest.results.analysis.key_takeaways)
        self.assertEqual("gemini-3.6-flash", manifest.results.analysis.model_name)
        self.assertEqual(1730000100000, manifest.results.analysis.generated_at)

    def test_round_trip_serialization_preserves_android_fields(self):
        manifest = JobManifest.from_json(self.android_json)
        serialized = manifest.to_json()
        round_tripped = json.loads(serialized)

        self.assertEqual("test-item-uuid-1234", round_tripped["item_id"])
        self.assertEqual("test-item-uuid-1234", round_tripped["job_id"])
        self.assertEqual("QUEUED", round_tripped["status"])
        self.assertEqual("SKIPPED", round_tripped["stages"]["acquisition"])
        self.assertEqual("SUCCEEDED", round_tripped["stages"]["audio_extraction"])
        self.assertEqual("drive_media_file_id_5678", round_tripped["media"]["drive_file_id"])
        self.assertEqual("drive_audio_file_id_9999", round_tripped["results"]["audio_drive_file_id"])
        self.assertEqual("Short productivity reel", round_tripped["results"]["analysis"]["summary"])


if __name__ == "__main__":
    unittest.main()
